import { useState, useEffect } from 'react';
import axios from 'axios';

const UserManager = () => {
  const [users, setUsers] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState({
    surname: '', name: '', patronymic: '', phone: '', password: '', role: 'user', vkId: '',
  });
  const [error, setError] = useState('');

  const fetchUsers = async () => {
    try {
      const res = await axios.get('/api/admin/users');
      setUsers(res.data);
    } catch { setError('Ошибка загрузки'); }
  };

  useEffect(() => { fetchUsers(); }, []);

  const resetForm = () => {
    setForm({ surname: '', name: '', patronymic: '', phone: '', password: '', role: 'user', vkId: '' });
    setEditingId(null);
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!form.surname || !form.name || !form.phone || (!editingId && !form.password)) {
      setError('Фамилия, имя, телефон и пароль обязательны');
      return;
    }
    try {
      if (editingId) {
        await axios.put(`/api/admin/users/${editingId}`, form);
      } else {
        await axios.post('/api/admin/users', form);
      }
      resetForm();
      fetchUsers();
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка сохранения');
    }
  };

  const handleEdit = (user) => {
    setEditingId(user.id);
    setForm({
      surname: user.surname,
      name: user.name,
      patronymic: user.patronymic || '',
      phone: user.phone,
      password: '',
      role: user.role,
      vkId: user.vkId || '',
    });
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить пользователя?')) {
      await axios.delete(`/api/admin/users/${id}`);
      fetchUsers();
    }
  };

  const handleChange = (e) => {
    setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  return (
    <div className="user-manager">
      <h2>Управление пользователями</h2>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleSubmit} className="user-form">
        <input name="surname" placeholder="Фамилия" value={form.surname} onChange={handleChange} required />
        <input name="name" placeholder="Имя" value={form.name} onChange={handleChange} required />
        <input name="patronymic" placeholder="Отчество" value={form.patronymic} onChange={handleChange} />
        <input name="phone" placeholder="Телефон" value={form.phone} onChange={handleChange} required />
        <input name="password" type="password" placeholder="Пароль" value={form.password} onChange={handleChange} required={!editingId} />
        <select name="role" value={form.role} onChange={handleChange}>
          <option value="user">Пользователь</option>
          <option value="employee">Работник</option>
          <option value="admin">Администратор</option>
        </select>
        {form.role === 'employee' && (
          <input name="vkId" type="number" placeholder="ID ВКонтакте" value={form.vkId} onChange={handleChange} />
        )}
        <div className="form-buttons">
          <button type="submit">{editingId ? 'Сохранить' : 'Создать'}</button>
          {editingId && <button type="button" onClick={resetForm}>Отмена</button>}
        </div>
      </form>

      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th><th>ФИО</th><th>Телефон</th><th>Роль</th><th>VK ID</th><th>Действия</th>
          </tr>
        </thead>
        <tbody>
          {users.map(u => (
            <tr key={u.id}>
              <td>{u.id}</td>
              <td>{u.surname} {u.name} {u.patronymic}</td>
              <td>{u.phone}</td>
              <td>{u.role}</td>
              <td>{u.vkId || '-'}</td>
              <td>
                <button onClick={() => handleEdit(u)}>✏️</button>
                <button onClick={() => handleDelete(u.id)}>🗑️</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default UserManager;
